/**
 * Procedural HDR sky used by the `env-sphere` scene: gradient sky + soft ground + a smooth "sun" hot spot.
 * Generated by `node bench/scenes/tier0/generate-assets.ts` into bench/assets/generated/ (no downloads).
 *
 * Equirectangular convention (the schema's `hdri`): row 0 = +Y (zenith), u = 0 at the −Z direction, increasing toward
 * +X (u = 0.25 is +X, 0.5 is +Z, 0.75 is −X). Pixel (i, j) is sampled at its centre.
 */
export const ENV_WIDTH = 512;
export const ENV_HEIGHT = 256;
export const ENV_FILE = 'generated/env-sky-512x256.pfm';

export const SUN_DIR: readonly [number, number, number] = (() => {
  const v = [0.55, 0.62, -0.56];
  const l = Math.hypot(v[0]!, v[1]!, v[2]!);
  return [v[0]! / l, v[1]! / l, v[2]! / l] as const;
})();
/** Angular standard deviation of the Gaussian sun profile, radians (5 degrees: well resolved at 0.7 deg/pixel). */
export const SUN_SIGMA = (5 * Math.PI) / 180;
export const SUN_PEAK = 40;

/** Radiance (linear Rec.709) seen along unit direction d (+Y up). */
export function skyRadiance(d: readonly [number, number, number]): [number, number, number] {
  const y = d[1];
  let r: number, g: number, b: number;
  if (y >= 0) {
    const t = Math.pow(1 - y, 2.5); // 0 at zenith, 1 at horizon
    r = 0.18 + (0.95 - 0.18) * t;
    g = 0.38 + (0.95 - 0.38) * t;
    b = 0.95 + (1.0 - 0.95) * t;
  } else {
    const t = Math.min(1, -y * 3);
    r = 0.55 + (0.2 - 0.55) * t;
    g = 0.5 + (0.17 - 0.5) * t;
    b = 0.45 + (0.12 - 0.45) * t;
  }
  const c = Math.min(1, Math.max(-1, d[0] * SUN_DIR[0] + d[1] * SUN_DIR[1] + d[2] * SUN_DIR[2]));
  const ang = Math.acos(c);
  const s = SUN_PEAK * Math.exp(-0.5 * (ang / SUN_SIGMA) ** 2);
  return [r + s * 1.0, g + s * 0.92, b + s * 0.75];
}

/** Direction for equirect coordinates u, v in [0,1] (v = 0 at +Y). */
export function equirectDirection(u: number, v: number): [number, number, number] {
  const phi = 2 * Math.PI * u;
  const theta = Math.PI * v;
  const st = Math.sin(theta);
  return [st * Math.sin(phi), Math.cos(theta), -st * Math.cos(phi)];
}

export function generateSkyImage(): Float32Array {
  const data = new Float32Array(ENV_WIDTH * ENV_HEIGHT * 3);
  for (let j = 0; j < ENV_HEIGHT; j++) {
    for (let i = 0; i < ENV_WIDTH; i++) {
      const c = skyRadiance(equirectDirection((i + 0.5) / ENV_WIDTH, (j + 0.5) / ENV_HEIGHT));
      data.set(c, (j * ENV_WIDTH + i) * 3);
    }
  }
  return data;
}
